def run():
    files = [f'test/live-source-{name}.test.ts' for name in TESTS]
    out = subprocess.run(['npx', 'vitest', 'run', '--root', str(COPY), *files, '--maxWorkers=2'], cwd=ROOT, capture_output=True, text=True)
    text = re.sub(r'\x1b\[[0-9;]*m', '', out.stdout + out.stderr)
    tests = re.search(r'^\s*Tests\s+(.*)$', text, re.M)
    failed = re.findall(r'^\s*[×✗]\s+(.*?)(?:\s+\d+ms)?$', text, re.M)
    return out.returncode, (tests.group(1).strip() if tests else 'no summary'), failed


def fresh_copy():
    if (COPY / 'src').exists():
        shutil.rmtree(COPY / 'src')
    shutil.copytree(ROOT / 'packages/shared/src', COPY / 'src')
    (COPY / 'test').mkdir(exist_ok=True)
    for name in TESTS:
        shutil.copy(ROOT / f'packages/shared/test/live-source-{name}.test.ts', COPY / 'test' / f'live-source-{name}.test.ts')


fresh_copy()
code, summary, _ = run()
print(f'M00 no change | exit {code} | {summary}')
assert code == 0, 'the copy must be green before a mutation'
survived = []
# Optional arguments: the IDs to run (for example `D09 E03`); without any, every mutation runs.
ONLY = set(sys.argv[1:])
if ONLY:
    M = [entry for entry in M if entry[0].split(' ')[0] in ONLY]
for name, file, old, new in M:
    pristine = (SOURCE / file).read_text()
    text = pristine
    assert text.count(old) == 1, f'{name}: the text to change occurs {text.count(old)} times in {file}'
    text = text.replace(old, new)
    target = COPY / 'src/live/source' / file
    target.write_text(text)
    code, summary, failed = run()
    target.write_text(pristine)
    verdict = 'KILLED' if code != 0 else 'SURVIVED'
    if code == 0:
        survived.append(name)
    first = failed[0] if failed else ''
    print(f'{name} [{file}] | {verdict} | {summary} | first: {first[:150]}', flush=True)
print(f'mutations: {len(M)}, killed: {len(M) - len(survived)}, survived: {len(survived)} {survived}')
